  function paintCheck(){
    if(!inp||!out)return;
    var r=checkMint(inp.value, CA);
    out.className='mint-check-out'+(r.state==='empty'?'':' '+r.state);
    out.textContent=r.message;
  }
  if(inp){ inp.addEventListener('input',paintCheck); inp.addEventListener('paste',function(){setTimeout(paintCheck,0);}); }
